/**
 * Render code-built emails to HTML (+ optional PNG screenshots and a
 * side-by-side against the design mockup).
 *
 *   npx tsx scripts/email-preview.ts [outDir=/tmp/nxeon-email-preview]
 *       [--only key1,key2]      only these SAMPLES keys
 *       [--png]                 also screenshot each at 600px and 390px (Playwright/Chromium)
 *       [--compare MOCKUP.png --panel key=N[,key=N]]
 *                               side-by-side: mockup panel N (1-8, the 4x2 board grid)
 *                               next to the 390px render of `key`, written as compare-<key>.png
 *
 * Uses lib/email-samples.ts (the same samples the tracking tests use).
 * Screenshots load the email's images from the LOCAL public/ folder (requests to
 * `${APP_URL}/email/...`, `/brand/...` and `/flags/...` are served from disk), so
 * new assets can be reviewed before they are deployed. Nothing is sent.
 */
import "../test/_cyrus-server-only-shim";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { SAMPLES } from "../lib/email-samples";
import { appUrl } from "../lib/email-render";

const args = process.argv.slice(2);
const flag = (n: string) => args.includes(n);
const opt = (n: string) => {
  const i = args.indexOf(n);
  return i >= 0 ? args[i + 1] : undefined;
};
const out = args[0] && !args[0].startsWith("--") ? args[0] : "/tmp/nxeon-email-preview";
const only = opt("--only")?.split(",").filter(Boolean);
mkdirSync(out, { recursive: true });

const keys = Object.keys(SAMPLES).filter((k) => !only || only.includes(k));
const rows: string[] = [];
for (const key of keys) {
  const b = SAMPLES[key]();
  writeFileSync(join(out, `${key}.html`), b.html);
  rows.push(`<li><a href="${key}.html">${key}</a> <small>${b.subject.replace(/</g, "&lt;")}</small></li>`);
}
if (!only) writeFileSync(join(out, "index.html"), `<!doctype html><meta charset="utf-8"><title>Nxeon emails</title><body style="font-family:sans-serif;background:#070a1a;color:#fff"><h1>${rows.length} templates</h1><ul>${rows.join("")}</ul>`);
console.log(`wrote ${rows.length} templates to ${out}`);

const MIME: Record<string, string> = { png: "image/png", jpg: "image/jpeg", jpeg: "image/jpeg", gif: "image/gif" };

async function shots() {
  // Playwright is a devDependency of the main tree; resolved at runtime only
  // (require, so NODE_PATH=/opt/nxeon/node_modules works from a bare worktree).
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const { chromium } = require("playwright") as typeof import("playwright");
  const browser = await chromium.launch();
  const pub = resolve(__dirname, "..", "public");
  const base = appUrl().replace(/\/+$/, "");
  const shoot = async (key: string, width: number) => {
    const page = await browser.newPage({ viewport: { width, height: 900 }, deviceScaleFactor: 2 });
    await page.route("**/*", (route) => {
      const u = route.request().url();
      if (u.startsWith(base + "/")) {
        const local = join(pub, decodeURIComponent(new URL(u).pathname));
        if (existsSync(local)) return route.fulfill({ body: readFileSync(local), contentType: MIME[local.split(".").pop()!.toLowerCase()] ?? "application/octet-stream" });
        return route.fulfill({ status: 404, body: "" });
      }
      return route.continue();
    });
    // Preview-only: a colour emoji font (the render host has none), like Gmail/Apple show.
    const html = readFileSync(join(out, `${key}.html`), "utf8").replace(
      "</head>",
      `<style>@import url('https://fonts.googleapis.com/css2?family=Noto+Color+Emoji&display=swap');h1{font-family:Inter,'Noto Color Emoji',sans-serif!important}</style></head>`
    );
    await page.setContent(html, { waitUntil: "networkidle", timeout: 60_000 }).catch(() => undefined);
    await page.evaluate(() => (document as any).fonts?.ready).catch(() => undefined);
    const file = join(out, `${key}${width === 600 ? "" : `@${width}`}.png`);
    await page.screenshot({ path: file, fullPage: true });
    await page.close();
    return file;
  };
  const made: Record<string, string> = {};
  for (const key of keys) {
    await shoot(key, 600);
    made[key] = await shoot(key, 390);
  }
  console.log(`screenshots: ${keys.length * 2} PNGs in ${out}`);

  const mockup = opt("--compare");
  const panels = (opt("--panel") ?? "").split(",").filter(Boolean).map((s) => s.split("=") as [string, string]);
  if (mockup && panels.length) {
    const mock = `data:image/png;base64,${readFileSync(mockup).toString("base64")}`;
    for (const [key, n] of panels) {
      if (!made[key]) continue;
      const idx = Number(n) - 1;
      // Board: 1024x1536, 4 columns x 2 rows of panels (measured from the image).
      const col = idx % 4, row = Math.floor(idx / 4);
      const px = [15, 267, 520, 773][col], py = [116, 852][row], pw = 238, ph = row ? 662 : 720;
      const render = `data:image/png;base64,${readFileSync(made[key]).toString("base64")}`;
      const H = 1500;
      const scale = H / ph;
      const page = await browser.newPage({ viewport: { width: 1400, height: H + 80 }, deviceScaleFactor: 1 });
      await page.setContent(`<html><body style="margin:0;background:#111;font-family:sans-serif;color:#ccc">
        <div style="display:flex;gap:30px;padding:20px">
          <div><div style="height:30px">Mockup panel ${n} (upscaled)</div><div style="width:${Math.round(pw * scale)}px;height:${H}px;background:url(${mock}) -${Math.round(px * scale)}px -${Math.round(py * scale)}px / ${Math.round(1024 * scale)}px auto no-repeat"></div></div>
          <div><div style="height:30px">Render: ${key} @390px</div><img src="${render}" style="width:${Math.round(pw * scale)}px;display:block"></div>
        </div></body></html>`);
      await page.screenshot({ path: join(out, `compare-${key}.png`), fullPage: true });
      await page.close();
    }
    console.log(`compare sheets: ${panels.map(([k]) => `compare-${k}.png`).join(", ")}`);
  }
  await browser.close();
}

if (flag("--png")) shots().catch((e) => {
  console.error("screenshots failed (is Playwright + Chromium installed?):", e);
  process.exitCode = 1;
});
