import "./_cyrus-server-only-shim";
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { SAMPLES, SAMPLE_UNSUB, catalogKeys } from "../lib/email-samples";
import { injectEmailTracking, emails } from "../lib/mailer";
import { containsSecretQueryParam, htmlToText, wrapEmail, BRAND, NX2 } from "../lib/email-render";

/**
 * Email overhaul guard (board card "Overhaul email templates"). Every code-built
 * email must (1) sit on the ONE shared shell, (2) keep every link / unsubscribe
 * hook the pre-overhaul template had (baseline fixture captured from main before
 * the change), and (3) still be trackable: open pixel + click rewrite work, and
 * bearer-secret links stay untouched.
 */
const APP = process.env.APP_URL ?? "https://nxeon.cloud";
const baseline = JSON.parse(readFileSync(join(__dirname, "fixtures", "email-tracking-inventory.json"), "utf8")) as Record<string, { subject: string; hrefs: string[] }>;
const hrefsOf = (html: string) => [...html.matchAll(/href="(https?:\/\/[^"]+)"/g)].map((m) => m[1].split(APP).join("{APP}"));

test("every template in the catalog has a sample (new emails cannot ship unchecked)", () => {
  const missing = catalogKeys().filter((k) => !(k in SAMPLES));
  assert.deepEqual(missing, []);
});

for (const [key, build] of Object.entries(SAMPLES)) {
  test(`${key}: shared shell, tracking hooks and plain text`, () => {
    const b = build();
    assert.ok(b.subject.length > 0);
    assert.ok(b.html.startsWith("<!doctype html>"), "full document");
    // Shell v1 (logo-email.png, BRAND.card) or shell v2 (2026-10 mockup: public/logo.png copy, NX2.card).
    assert.ok(b.html.includes("/brand/logo-email.png") || b.html.includes("/email/nxeon-logo.png"), "logo header");
    assert.ok(b.html.includes("NXEON CLOUD") || b.html.includes("CYRUS"), "footer");
    assert.ok(b.html.includes(BRAND.card) || b.html.includes(NX2.card), "dark card");
    assert.ok(!/\{\{|undefined|\[object Object\]/.test(b.html), "no unrendered placeholders");
    assert.ok(b.html.trimEnd().endsWith("</body></html>"), "</body> last so the pixel can be injected");

    // Every pre-overhaul link is still present (multiset subset).
    const before = baseline[key];
    if (before && !before.subject.startsWith("ERROR")) {
      const now = hrefsOf(b.html);
      const pool = [...now];
      for (const h of before.hrefs) {
        const i = pool.indexOf(h);
        // flashSale's old Outlook VML duplicated the CTA href; one copy is enough.
        if (i < 0 && key === "flashSale" && now.includes(h)) continue;
        assert.ok(i >= 0, `${key}: lost link ${h}`);
        pool.splice(i, 1);
      }
    }

    // Tracking: pixel appended, every non-secret absolute link rewritten, secrets untouched.
    const t = injectEmailTracking(b.html, "log-1");
    assert.equal((t.html.match(/\/api\/track\/email\/log-1\/open/g) ?? []).length, 1, "one open pixel");
    for (const h of hrefsOf(b.html).map((x) => x.split("{APP}").join(APP))) {
      const secret = containsSecretQueryParam(h) || h.includes("/api/outreach/unsubscribe");
      if (secret) assert.ok(t.html.includes(`href="${h}"`), `secret/unsubscribe link must stay direct: ${h}`);
      else assert.ok(t.links.includes(h), `link not tracked: ${h}`);
    }
    // Plain-text alternative: real content, no CSS/markup leakage.
    const text = htmlToText(b.html);
    assert.ok(text.length > 40);
    assert.ok(!/[{};]\s*\.nx-|<\w+|@media/.test(text), "no CSS or tags in text part");
  });
}

