/* Availability, recorded and read.
 *
 * Proxmox cannot answer "what was this VM's uptime last month" — `vmStatus`
 * reports only the present, and the RRD series carries load, not up/down. So
 * the worker samples on a cadence (worker/uptime.ts) and this file owns both
 * ends of that: `recordSample` writes, `uptimePercent` reads.
 *
 * The one rule worth stating out loud: a day with no samples is NOT 0% uptime,
 * it is "not measured". Averaging unmeasured days in would report an outage
 * that never happened — which is worse than reporting nothing, because a
 * customer would act on it. Every read below skips days where total === 0. */

export const UPTIME_WINDOW_DAYS = 30;

/** UTC midnight for a timestamp — the key each day's counters live under. */
export function utcDay(at: Date = new Date()): Date {
  return new Date(Date.UTC(at.getUTCFullYear(), at.getUTCMonth(), at.getUTCDate()));
}

/**
 * Fold one observation into today's counters. Called once per server per sweep.
 * Upsert rather than read-modify-write so two workers sampling concurrently
 * cannot lose an increment.
 */
export async function recordSample(serverId: string, up: boolean, at: Date = new Date()) {
  const date = utcDay(at);
  await db.serverUptimeDaily.upsert({
    where: { serverId_date: { serverId, date } },
    create: { serverId, date, up: up ? 1 : 0, total: 1 },
    update: { up: { increment: up ? 1 : 0 }, total: { increment: 1 } },
  });
}

export type UptimeRead = {
  /** null when nothing was measured in the window — render "—", never "0%". */
  percent: number | null;
  /** How many samples the number rests on, so a caller can judge it. */
  samples: number;
  days: number;
};

/**
 * Availability across every server passed, over the trailing window.
 *
 * Pooled, not a mean-of-means: a server measured for two days should not weigh
 * the same as one measured for thirty. Summing samples first gives the honest
 * figure — the share of all observations in which the estate was up.
 */
export async function uptimeFor(serverIds: string[], windowDays = UPTIME_WINDOW_DAYS): Promise<UptimeRead> {
  if (serverIds.length === 0) return { percent: null, samples: 0, days: 0 };
  const since = utcDay(new Date(Date.now() - windowDays * 86_400_000));

  const rows = await db.serverUptimeDaily.findMany({
    where: { serverId: { in: serverIds }, date: { gte: since }, total: { gt: 0 } },
    select: { up: true, total: true, date: true },
  });
  if (rows.length === 0) return { percent: null, samples: 0, days: 0 };

  const up = rows.reduce((n, r) => n + r.up, 0);
  const total = rows.reduce((n, r) => n + r.total, 0);
  const days = new Set(rows.map((r) => r.date.getTime())).size;

  // Two decimals: the figure the design shows is "99.98%", and rounding to a
  // whole number would collapse every good month onto "100%".
  return { percent: Math.round((up / total) * 10_000) / 100, samples: total, days };
}

/** "99.98%" / "—". Formatting lives here so every surface agrees. */
export function formatUptime(read: UptimeRead): string {
  return read.percent === null ? "—" : `${read.percent.toFixed(2)}%`;
}
