// Cyrus notification copy + email templates (r40). PURE, client-safe. One function per event builds the in-app title /
// body / link and the email (subject, HTML, plain text) from the event's data only (no invented figures).
// Visual language: the cyrus.my landing (near-black #050508, white type, electric blue #3d7bff -> violet #8b5cff
// accents), table layout + inline styles so it renders in every mail client, dark by design.
import type { NotifyEvent } from "./events";

const STUDIO = "/dashboard/cyrus"; // CYRUS_STUDIO_PATH (lib/cyrus/public-gate.ts); cyrus.my serves the same app

export type Rendered = { title: string; body: string; href: string | null; subject: string; html: string; text: string };
export type RenderCtx = { appBase: string; prefsUrl: string };

const esc = (s: unknown) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!);
const str = (d: Record<string, unknown>, k: string, max = 120) => String(d[k] ?? "").replace(/[\r\n]+/g, " ").slice(0, max);
const safeHref = (base: string, path: string) => (/^\/[A-Za-z0-9/_?=&.%-]*$/.test(path) ? `${base.replace(/\/$/, "")}${path}` : base);

function copy(ev: NotifyEvent, d: Record<string, unknown>): { title: string; body: string; path: string | null; cta: string } {
  const name = str(d, "name") || "your mod";
  switch (ev) {
    case "build.finished": {
      const ok = d.status === "succeeded";
      return { title: ok ? `${name} is built` : `${name} did not build`, body: ok ? "Your build finished. Check its Test Flight result, then install it on a server or keep changing it." : `The build stopped${str(d, "reason") ? `: ${str(d, "reason", 200)}` : "."} The build page shows what happened and what was charged. A build that fails on our side is not charged.`, path: d.buildId ? `${STUDIO}/${encodeURIComponent(str(d, "buildId", 64))}` : STUDIO, cta: ok ? "Open the build" : "See what happened" };
    }
    case "install.result": {
      const ok = d.ok === true;
      return { title: ok ? `${name} is on ${str(d, "server") || "your server"}` : `${name} was not installed`, body: ok ? (d.restartRequired ? "Installed. Restart the server to load it." : "Installed and loaded.") : `The install did not finish${str(d, "reason") ? `: ${str(d, "reason", 200)}` : "."} Cyrus undid its changes where it could. Open Cyrus to confirm the state of your server, or roll back to your previous build.`, path: STUDIO, cta: "Open Cyrus" };
    }
    case "mod.outdated":
      return { title: `${name} may need a rebuild`, body: `${str(d, "game") || "The game"} ${str(d, "version") ? `moved to ${str(d, "version")}` : "was updated"}. Your mod was built for ${str(d, "builtFor") || "an older version"}; rebuild it to keep it working. You see the cost before you rebuild.`, path: d.buildId ? `${STUDIO}/${encodeURIComponent(str(d, "buildId", 64))}` : STUDIO, cta: "Rebuild" };
    case "takedown":
      return { title: `${name} was taken down`, body: `${str(d, "what") || "Content"} was removed${str(d, "reason") ? ` (${str(d, "reason", 200)})` : ""}. Projects that used it keep their own copy and keep working.${d.counterNotice ? " If you believe this is a mistake, you can send a counter-notice by replying to this email." : ""}`, path: STUDIO, cta: "Open Cyrus" };
    case "tokens.low":
      return { title: "Your Cyrus tokens are running low", body: `${str(d, "available") ? `${str(d, "available")} tokens left.` : "Your balance is low."} Top up or change plan to keep building. Your mods and installs are not affected.`, path: STUDIO, cta: "Get tokens" };
  }
}

