/**
 * Brand palette. Since the 2026-10 email rollout every email (code-built, DB
 * template bodies, worker/admin sends) renders on shell v2 (`wrapEmail2`), so
 * these tokens ARE the v2 mockup palette. Key names are kept from the earlier
 * themes so existing consumers re-theme without edits.
 */
export const BRAND = {
  // Primary accent (buttons, gradient)
  violet: "#7c3aed",
  violetLight: "#9152ff",
  violetDeep: "#7a3ff6",
  cyan: "#3edcf2",
  /** Readable-on-navy violet for TEXT (links, eyebrows, bullets). */
  link: "#b69cff",
  // Surfaces
  pageBg: "#04060f",
  card: "#10162a",
  panel: "#10162a",
  panelBorder: "#242b45",
  hair: "#1a2034",
  // Ink
  ink: "#ffffff",
  body: "#c5c9d6",
  muted: "#8a90a6",
  faint: "#555c76",
  // Status (text/accent colours are the light variants so they read on navy)
  success: "#34d399",
  successBg: "#0b2420",
  warn: "#fbbf24",
  warnBg: "#2a2110",
  danger: "#f87171",
  dangerBg: "#2b1220",
  info: "#b69cff",
  infoBg: "#171b3c",
};
const FONT = "Inter,-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";

export function appUrl(): string {
  return process.env.APP_URL ?? "https://nxeon.cloud";
}

const esc = (s: unknown) =>
  String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

/**
 * Make trusted inline markup readable on the navy card: anchors without their
 * own style get the link colour (default browser blue is unreadable on dark),
 * bare <b>/<strong> turn white. Pure string work, idempotent.
 */
function themeInline(html: string): string {
  return String(html ?? "")
    .replace(/<a\s+(?![^>]*\bstyle=)([^>]*?)>/gi, `<a $1 style="color:${BRAND.link};text-decoration:underline;">`)
    .replace(/<(b|strong)>/gi, `<$1 style="color:${BRAND.ink};font-weight:600;">`);
}

/**
 * Legacy light-theme literals that still live in DB-stored template bodies
 * (EmailTemplate rows seeded before the dark theme). Mapped onto the new tokens
 * so an old row stays legible instead of rendering dark-on-dark.
 */
function remapLegacyColors(html: string): string {
  return html
    .replace(/color:\s*#6f47f5/gi, `color:${BRAND.link}`)
    .replace(/color:\s*#8a70fb/gi, `color:${BRAND.link}`)
    .replace(/color:\s*#15a34a/gi, `color:${BRAND.success}`)
    .replace(/color:\s*#1c1638/gi, `color:${BRAND.ink}`)
    .replace(/color:\s*#4a4763/gi, `color:${BRAND.body}`);
}

// ---------------------------------------------------------------------------
// Reusable, fully-inline email components. Every template composes these so the
// look stays consistent. All return an HTML string. They are styled to the v2
// mockup (cards with hairline rows, full-width gradient buttons). The leading
// eyebrow / headline / first short paragraph are tagged with data-nx markers so
// `wrapEmail` can lift them into the hero band (see `liftHero`).
// ---------------------------------------------------------------------------

export type Accent = "violet" | "success" | "warn" | "danger" | "info";
const accentColor = (a: Accent = "violet") =>
  a === "success" ? BRAND.success : a === "warn" ? BRAND.warn : a === "danger" ? BRAND.danger : a === "info" ? BRAND.info : BRAND.link;
/** Solid button / bar colour (the saturated one, not the text-on-navy variant). */
const accentSolid = (a: Accent = "violet") =>
  a === "success" ? "#10b981" : a === "warn" ? "#d97706" : a === "danger" ? "#dc2626" : BRAND.violet;
const accentGrad = (a: Accent = "violet") =>
  a === "success"
    ? "linear-gradient(90deg,#059669 0%,#10b981 100%)"
    : a === "warn"
      ? "linear-gradient(90deg,#d97706 0%,#f59e0b 100%)"
      : a === "danger"
        ? "linear-gradient(90deg,#dc2626 0%,#ef4444 100%)"
        : "linear-gradient(90deg,#7a3ff6 0%,#9152ff 100%)";
const accentBg = (a: Accent = "violet") =>
  a === "success" ? BRAND.successBg : a === "warn" ? BRAND.warnBg : a === "danger" ? BRAND.dangerBg : BRAND.infoBg;
const accentBorder = (a?: Accent) =>
  a === "success" ? "#1d6b52" : a === "warn" ? "#7a5a14" : a === "danger" ? "#7a2a3a" : a === "info" ? "#3a3a7a" : BRAND.panelBorder;
export const emailDefaultGlyph: Record<Accent, string> = {
  violet: "&#9733;", // ★
  success: "&#10003;", // ✓
  warn: "!",
  danger: "&#10005;", // ✕
  info: "i",
};
/** Hero badge (public/email/badges/<name>.png) used when a template names none. */
const DEFAULT_BADGE: Record<Accent, string> = { violet: "star", success: "check", warn: "alert", danger: "alert-danger", info: "shield" };

/** Small uppercase eyebrow/kicker label above the headline (lifted into the hero). */
export function emailEyebrow(text: string, accent: Accent = "violet"): string {
  return `<div data-nx="eyebrow" data-accent="${accent}" style="margin:0 0 12px;font-family:${FONT};font-size:13px;font-weight:700;letter-spacing:1.8px;text-transform:uppercase;color:${accentColor(accent)};">${esc(text)}</div>`;
}

/**
 * Legacy glyph tile. The shell now shows a proper hero badge image instead, so
 * when this leads a body `wrapEmail` drops it (keeping only its accent). Still
 * rendered as a small tile when used deep inside a body.
 */
export function emailIconTile(glyph: string, accent: Accent = "violet", size = 52): string {
  const fs = Math.round(size * 0.46);
  return `<table data-nx="tile" data-accent="${accent}" role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 18px;"><tr><td align="center" valign="middle" width="${size}" height="${size}" bgcolor="${accentBg(accent)}" style="width:${size}px;height:${size}px;background-color:${accentBg(accent)};border:1px solid ${accentBorder(accent)};border-radius:${Math.round(size * 0.28)}px;font-family:${FONT};font-size:${fs}px;line-height:${size}px;font-weight:700;color:${accentColor(accent)};text-align:center;">${glyph}</td></tr></table>`;
}

/** Main headline (lifted into the hero). */
export function emailHeading(text: string): string {
  return `<h1 data-nx="h1" class="nx-h1" style="margin:0 0 14px;font-family:${FONT};font-size:32px;line-height:1.2;font-weight:800;letter-spacing:-0.6px;color:${BRAND.ink};">${esc(text)}</h1>`;
}

/** Body paragraph. `html` may contain trusted inline markup (links, <b>). */
export function emailParagraph(html: string): string {
  return `<p data-nx="p" style="margin:0 0 16px;font-family:${FONT};font-size:15px;line-height:24px;color:${BRAND.body};">${themeInline(html)}</p>`;
}

/** Small muted note (fine print, alternate-link fallback, etc). */
export function emailNote(html: string): string {
  return `<p style="margin:18px 0 0;font-family:${FONT};font-size:13px;line-height:21px;color:${BRAND.muted};">${themeInline(html)}</p>`;
}

/** Full-width bulletproof CTA (bgcolor + padding so it survives Outlook). */
export function emailButton(href: string, label: string, accent: Accent = "violet"): string {
  const bg = accentSolid(accent);
  const shadow = accent === "violet" || accent === "info" ? "box-shadow:0 10px 28px rgba(124,58,237,0.38);" : "";
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:10px 0 6px;"><tr><td class="nx-btn" align="center" bgcolor="${bg}" style="background-color:${bg};background-image:${accentGrad(accent)};border-radius:12px;${shadow}">
    <a href="${href}" style="display:block;padding:17px 20px;font-family:${FONT};font-size:16px;font-weight:700;line-height:20px;color:#ffffff;text-decoration:none;border-radius:12px;">${esc(label)}&nbsp;<span style="font-size:1.15em;line-height:1;">&#10142;</span></a>
  </td></tr></table>`;
}

/** Rounded card framing a details table / highlighted content. */
export function emailPanel(innerHtml: string, accent?: Accent): string {
  const bd = accentBorder(accent);
  const bg = accent && accent !== "violet" && accent !== "info" ? accentBg(accent) : BRAND.card;
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="${bg}" style="margin:8px 0 18px;background-color:${bg};background-image:linear-gradient(180deg,${accent && accent !== "violet" && accent !== "info" ? bg : "#151c33"} 0%,${accent && accent !== "violet" && accent !== "info" ? bg : "#0c1121"} 100%);border:1px solid ${bd};border-radius:16px;">
    <tr><td style="padding:14px 22px;">${innerHtml}</td></tr></table>`;
}

