    <td valign="middle" style="padding:12px 12px 12px 12px;font-family:${FONT2};"><div style="font-size:16px;line-height:21px;font-weight:700;color:${NX2.ink};">${esc(a.title)}</div>${a.sub ? `<div style="font-size:13px;line-height:18px;color:${NX2.muted};padding-top:2px;word-break:break-all;">${esc(a.sub)}</div>` : ""}</td>
