        `<td width="${w}%" valign="top" style="width:${w}%;padding:0 ${i === n - 1 ? 0 : 6}px 0 ${i === 0 ? 0 : 6}px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="${NX2.tile}" style="background-color:${NX2.tile};background-image:linear-gradient(180deg,${NX2.tileTop} 0%,${NX2.tile} 100%);border:1px solid ${NX2.tileBorder};border-radius:16px;"><tr><td class="nx2-stat" align="center" style="padding:18px 6px;font-family:${FONT2};"><div style="font-size:30px;line-height:34px;font-weight:800;color:${NX2.ink};">${esc(t.value)}</div><div style="font-size:12px;line-height:17px;color:${NX2.muted};padding-top:4px;">${esc(t.label)}</div></td></tr></table></td>`
    )
    .join("");
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>${cells}</tr></table>`;
}

/** Centered row of country flags with a code under each (public/email/flags). */
export function emailFlagRow2(flags: Array<{ cc: string; label: string }>): string {
