    )
    .join("");
  return `<table role="presentation" cellpadding="0" cellspacing="0" border="0" align="center"><tr>${cells}</tr></table>`;
}

/** Stacked article cards: thumbnail left, title + "Read Guide" right, each a link. */
export function emailArticleCards2(items: Array<{ title: string; href: string; image: string; cta?: string; sub?: string }>): string {
  return items
    .map(
      (it, i) =>
        `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="${NX2.tile}" style="margin:0 0 ${i === items.length - 1 ? 0 : 14}px;background-color:${NX2.tile};background-image:linear-gradient(180deg,${NX2.tileTop} 0%,${NX2.tile} 100%);border:1px solid ${NX2.tileBorder};border-radius:16px;"><tr>
      <td class="nx2-art-th" width="150" valign="middle" style="width:150px;padding:10px;"><a href="${it.href}" style="text-decoration:none;"><img src="${it.image}" width="130" height="94" alt="${esc(it.title)}" style="display:block;width:130px;height:94px;border:0;border-radius:10px;" /></a></td>
      <td valign="middle" style="padding:12px 16px 12px 4px;font-family:${FONT2};"><a href="${it.href}" style="text-decoration:none;display:block;"><span style="display:block;font-size:16px;line-height:21px;font-weight:700;color:${NX2.ink};">${esc(it.title)}</span>${it.sub ? `<span style="display:block;font-size:13px;line-height:18px;color:${NX2.muted};padding-top:4px;">${esc(it.sub)}</span>` : ""}<span style="display:block;font-size:14px;line-height:20px;font-weight:600;color:${NX2.link};padding-top:8px;">${esc(it.cta ?? "Read Guide")} &rarr;</span></a></td>
    </tr></table>`
    )
    .join("");
}

/** Full-width image (banner / art). Always absolute URL + width/height + alt. */
