}

/** Banner with a bold line over the lower-left of the picture (background image td). */
export function emailBannerArt2(a: { src: string; h: number; title: string; sub?: string; href?: string }): string {
  const inner = `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" height="${a.h}"><tr><td valign="bottom" height="${a.h}" background="${a.src}" bgcolor="${NX2.shell}" style="height:${a.h}px;background-color:${NX2.shell};background-image:linear-gradient(180deg,rgba(4,6,15,0) 35%,rgba(4,6,15,0.82) 100%),url('${a.src}');background-size:cover;background-position:center;border-radius:16px;padding:0 22px 20px;font-family:${FONT2};">
