  </td></tr></table>`;
  return a.href ? `<a href="${a.href}" style="text-decoration:none;display:block;">${inner}</a>` : inner;
}

/**
 * Invoice card: number + date header, line items, optional subtotal / tax, a
 * bold total and (optionally) a status pill. Amounts arrive pre-formatted.
