 * Pure: no DB, no network.
 */
import {
  wrapEmail,
  emailButton,
  emailHeading,
  emailEyebrow,
  emailNote,
  emailIconTile,
  emailDefaultGlyph,
  emailAsset,
  emailServerRow2,
  type Accent,
  type PillTone,
  type EmailSocial,
} from "./email-render";
import { EMAIL_GAME_ART } from "./email-game-art";
import { GAME_DISPLAY, type GameFamily } from "./games";

export type BuiltEmail = { template: string; subject: string; html: string };

/** Hero + tile image URLs for a game family (default art when there is none). */
export function emailGameArt(family?: string | null): { known: boolean; family: string | null; hero: string; tile: string; name: string | null } {
  const fam = family && EMAIL_GAME_ART.has(family) ? family : null;
  const name = family && family in GAME_DISPLAY ? GAME_DISPLAY[family as GameFamily].name : null;
  return {
    known: !!fam,
    family: fam,
    hero: emailAsset(fam ? `games/hero-${fam}.jpg` : "games/hero-default.jpg"),
    tile: emailAsset(fam ? `games/tile-${fam}.png` : "games/tile-default.png"),
    name,
  };
}

export type ServerRef = {
  hostname: string;
  /** GameFamily slug when the server is a game server and the family is known. */
  gameFamily?: string | null;
  sub?: string;
  pill?: string;
  pillTone?: PillTone;
};

export type BuildOpts = {
  template: string;
  subject: string;
  preheader: string;
  eyebrow?: string;
  accent?: Accent;
  heading: string;
  blocks: string[];
  cta?: { href: string; label: string; accent?: Accent };
  note?: string;
  /** Legacy glyph (ignored by the hero; kept so older call sites compile). */
  icon?: string;
  /** public/email/badges/<name>.png shown in the hero when the email has no game art. */
  badge?: string;
  /** The game family this email concerns, when known: hero art + tile of that game. */
  gameFamily?: string | null;
  /** Adds the compact "this server" row (game tile + hostname) after the lead. */
  server?: ServerRef;
  socials?: EmailSocial[];
};

export function build(opts: BuildOpts): BuiltEmail {
  const accent = opts.accent ?? "violet";
  const fam = opts.gameFamily ?? opts.server?.gameFamily ?? null;
  const art = emailGameArt(fam);
  const blocks = [...opts.blocks];
  if (opts.server) {
    const s = opts.server;
    const a = emailGameArt(s.gameFamily ?? fam);
    const row = `<div style="margin:6px 0 18px;">${emailServerRow2({
      tile: { src: a.tile, alt: a.name ?? "Server" },
      title: s.hostname,
      sub: s.sub ?? (a.name ? `${a.name} server` : "Cloud VPS"),
      pill: s.pill,
      pillTone: s.pillTone,
    })}</div>`;
    const lead = blocks[0] && blocks[0].startsWith('<p data-nx="p"') ? 1 : 0;
    blocks.splice(lead, 0, row);
  }
  const parts: string[] = [];
  parts.push(emailIconTile(opts.icon ?? emailDefaultGlyph[accent], accent));
  if (opts.eyebrow) parts.push(emailEyebrow(opts.eyebrow, accent));
  parts.push(emailHeading(opts.heading));
  parts.push(...blocks);
  if (opts.cta) parts.push(emailButton(opts.cta.href, opts.cta.label, opts.cta.accent ?? accent));
  if (opts.note) parts.push(emailNote(opts.note));
  return {
    template: opts.template,
    subject: opts.subject,
    html: wrapEmail(parts.join("\n"), {
      preheader: opts.preheader,
      accent,
      badge: opts.badge,
      heroImage: art.known ? art.hero : undefined,
      socials: opts.socials,
    }),
  };
}
