/**
 * Pure derivations of the "real numbers" the marketing-style emails may show.
 * Nothing here is invented: every figure comes from an input the caller read
 * from the database (enabled nodes, uptime counters) or is omitted.
 */
import { REGION_COUNTRY, customerRegionLabel } from "./node-regions";
import { continentOf } from "./geo-continent";

export type LocationStats = {
  /** Distinct live datacenter regions (Node.region of enabled nodes). */
  count: number;
  /** Region codes, de-duplicated, in input order. */
  regions: string[];
  /** Distinct ISO2 country codes (lowercase) with a flag asset. */
  countries: string[];
  continents: number;
};

export function locationStatsFromRegions(regionCodes: string[]): LocationStats {
  const regions = [...new Set(regionCodes.filter(Boolean))];
  const countries = [...new Set(regions.map((r) => REGION_COUNTRY[r]).filter((c): c is string => !!c))];
  const continents = new Set(countries.map((c) => continentOf(c)).filter(Boolean)).size;
  return { count: regions.length, regions, countries, continents };
}

export const plural = (n: number, one: string, many = `${one}s`) => `${n} ${n === 1 ? one : many}`;

/** "3 locations across 3 continents", or null when there is nothing real to say. */
export function locationsLine(s: LocationStats | null | undefined): string | null {
  if (!s || s.count < 1) return null;
  return s.continents > 0 ? `${plural(s.count, "location")} across ${plural(s.continents, "continent")}` : plural(s.count, "location");
}

export const regionName = customerRegionLabel;

/**
 * Pooled availability from raw daily counters. Returns null (tile omitted) when
 * the window holds too little data to be a fair number: fewer than 14 measured
 * days or fewer than 1000 samples. Never rounds up to 100.
 */
export function uptimeLabel(rows: { up: number; total: number; days: number }): string | null {
  if (rows.days < 14 || rows.total < 1000) return null;
  const pct = Math.floor((rows.up / rows.total) * 10_000) / 100;
  return `${pct.toFixed(2)}%`;
}
