import "server-only";
/**
 * Database reads for the marketing-style emails (locations, uptime, guides).
 * Kept apart from the pure builders so lib/email-templates.ts stays DB-free.
 * Every loader fails soft: on error it returns null / [] and the email simply
 * omits what it could not verify.
 */
import { db } from "./db";
import { locationStatsFromRegions, uptimeLabel, type LocationStats } from "./email-stats";
import { REGION_COUNTRY } from "./node-regions";

/** Live datacenters = distinct regions of enabled nodes. */
export async function getLocationStats(): Promise<LocationStats | null> {
  try {
    const nodes = await db.node.findMany({ where: { enabled: true }, select: { region: true } });
    const s = locationStatsFromRegions(nodes.map((n) => n.region));
    return s.count ? s : null;
  } catch {
    return null;
  }
}

/** Platform-wide measured availability over the last 30 days, or null when it is not a fair number. */
export async function getUptimeLabel(): Promise<string | null> {
  try {
    const since = new Date(Date.now() - 30 * 86_400_000);
    since.setUTCHours(0, 0, 0, 0);
    const [agg, days] = await Promise.all([
      db.serverUptimeDaily.aggregate({ where: { date: { gte: since }, total: { gt: 0 } }, _sum: { up: true, total: true } }),
      db.serverUptimeDaily.groupBy({ by: ["date"], where: { date: { gte: since }, total: { gt: 0 } } }),
    ]);
    return uptimeLabel({ up: agg._sum.up ?? 0, total: agg._sum.total ?? 0, days: days.length });
  } catch {
    return null;
  }
}

export type TipArticle = { title: string; href: string; category: string; image?: string };

/** Newest published blog posts as guide cards (real titles + canonical URLs). */
export async function getTipArticles(limit = 3, base = process.env.APP_URL ?? "https://nxeon.cloud"): Promise<TipArticle[]> {
  try {
    const posts = await db.blogPost.findMany({
      where: { published: true },
      orderBy: [{ publishedAt: "desc" }, { createdAt: "desc" }],
      take: limit,
      select: { slug: true, title: true, category: true, coverImage: true },
    });
    return posts.map((p) => ({
      title: p.title,
      href: `${base}/blog/${p.slug}`,
      category: p.category,
      image: p.coverImage && /^(https?:\/\/|\/)[^\s]+\.(png|jpe?g)$/i.test(p.coverImage) ? (p.coverImage.startsWith("/") ? `${base}${p.coverImage}` : p.coverImage) : undefined,
    }));
  } catch {
    return [];
  }
}

/** Region of a server's node -> ISO2 (for flag rows). */
export const regionCountry = (region: string) => REGION_COUNTRY[region];
