// ---------------------------------------------------------------- (b) invoice
export type InvoiceDesignArgs = {
  invoiceNumber: string;
  amount: string;
  dueDate: string;
  description: string;
  renewal?: string | null;
  items?: Array<{ label: string; amount: string }>;
  subtotal?: string;
  tax?: { label: string; amount: string };
  total?: string;
  payUrl?: string;
  /** Real Server.autoRenew when the sender knows it; undefined = unknown. */
  autoPay?: boolean;
  hostname?: string;
  gameFamily?: string | null;
};

export function invoiceDesign(a: InvoiceDesignArgs, o: { invoiceAttached: boolean; paid: boolean } & Common): BuiltEmail {
  const items = a.items?.length ? a.items : [{ label: a.description, amount: a.amount }];
  const showSub = !!a.subtotal || items.length > 1;
  const subtotal = a.subtotal ?? (showSub ? a.amount : undefined);
  const total = a.total ?? a.amount;
  const attach = o.invoiceAttached ? "The itemised invoice is attached to this email." : "You can view and download the itemised invoice from your billing history.";
  const lead = o.paid
    ? `This invoice has already been paid in full, nothing more is owed. ${attach}`
    : `Your next payment is ready. Keep your server online and uninterrupted. ${attach}`;
  const rows: string[] = [
    emailHero2({
      eyebrow: o.paid ? "Invoice paid" : "Invoice ready",
      title: o.paid ? "Your invoice\nis paid" : "Your invoice\nis ready",
      text: lead,
      accent: o.paid ? "success" : "violet",
      badge: o.paid ? "receipt" : "receipt",
    }),
    emailSection2(
      emailInvoiceCard2({
        number: a.invoiceNumber,
        date: `${o.paid ? "Paid" : "Due"} ${a.dueDate}`,
        items,
        subtotal,
        tax: a.tax,
        total,
        pill: o.paid ? "Paid" : undefined,
      }),
      "6px 40px 16px"
    ),
  ];
  if (a.renewal) rows.push(emailSection2(emailNote2(esc(a.renewal.replace(/^Renews at /, "Renews "))), "0 40px 14px"));
  rows.push(emailSection2(emailButton2(o.payUrl ?? p("/dashboard/invoices"), o.paid ? "View Invoice" : "Pay Invoice"), "0 40px 22px"));
  // Auto Pay explainer: only when it is useful (an unpaid invoice, or auto pay known to be off).
  if (!o.paid || a.autoPay === false) {
    const state = a.autoPay === true ? "On" : a.autoPay === false ? "Off" : undefined;
    rows.push(
      emailSection2(
        emailCard2(
          `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td valign="top" style="font-family:${"Inter,-apple-system,Segoe UI,Arial,sans-serif"};"><div style="font-size:17px;line-height:23px;font-weight:700;color:#fff;">Auto Pay</div><div style="font-size:14px;line-height:21px;color:${NX2.label};padding-top:4px;">Enable automatic payments to avoid any interruptions to your service.</div></td>${state ? `<td width="70" valign="top" align="right">${emailPill2(state, state === "On" ? "success" : "warn")}</td>` : ""}</tr></table>`
        ),
        "0 40px 16px"
      ),
      emailSection2(
        emailCard2(
          `<div style="font-family:Inter,-apple-system,Segoe UI,Arial,sans-serif;font-size:17px;line-height:23px;font-weight:700;color:#fff;margin:0 0 14px;">Why keep Auto Pay on?</div>${emailList(["No downtime", "Keep your server online", "Less to worry about"])}<a href="${p("/dashboard/billing")}" style="font-family:Inter,-apple-system,Segoe UI,Arial,sans-serif;font-size:14px;font-weight:600;color:${NX2.link};text-decoration:none;">Manage Auto Pay &rarr;</a>`,
          "22px 24px 20px"
        ),
        "0 40px 22px"
      )
    );
  }
  return {
    template: "invoice_new",
    subject: o.paid ? `Invoice #${a.invoiceNumber} — paid` : `Invoice #${a.invoiceNumber} — ${a.amount} due`,
    html: wrapEmail2(rows.join("\n"), {
      preheader: o.paid ? `Your invoice #${a.invoiceNumber} for ${a.amount} has been paid.` : `Your invoice #${a.invoiceNumber} for ${a.amount} is ready.`,
      socials: o.socials,
    }),
  };
}

// --------------------------------------------------------------- (c) renewal
export type RenewalDesignArgs = {
  hostname: string;
  /** Pre-formatted renewal date. */
  date: string;
  daysLeft?: number | null;
  amount?: string | null;
  gameFamily?: string | null;
  planName?: string | null;
  /** "wallet": top up the wallet; "card": no payment method on file (add one). */
  mode: "wallet" | "card";
  ctaUrl: string;
};

export function renewalDesign(a: RenewalDesignArgs & Common): BuiltEmail {
  const art = emailGameArt(a.gameFamily);
  const days = a.daysLeft != null && a.daysLeft >= 0 ? (a.daysLeft === 0 ? "Today" : plural(a.daysLeft, "day")) : null;
  const sub = [art.name ? `${art.name} server` : "Cloud VPS", a.planName].filter(Boolean).join(" · ");
  const lead =
    a.mode === "card"
      ? `Your server renews soon and there is no payment method on file. Add a card now and the renewal is charged automatically, so nothing goes offline.`
      : `Your service will renew soon. Make sure your wallet balance covers it to avoid any downtime.`;
  const card = `<div style="font-family:Inter,-apple-system,Segoe UI,Arial,sans-serif;">
      <div style="font-size:15px;line-height:20px;color:${NX2.label};">Renews ${days ? "in" : "on"}</div>
      <div style="font-size:34px;line-height:42px;font-weight:800;color:${NX2.link};padding:2px 0 14px;">${esc(days ?? a.date)}</div>
      ${emailServerRow2({ tile: { src: art.tile, alt: art.name ?? "Server" }, title: a.hostname, sub })}
      <div style="height:6px;line-height:6px;font-size:0;">&nbsp;</div>
      ${emailKeyValue([["Renewal Date", esc(a.date)], ...(a.amount ? ([["Amount", esc(a.amount)]] as [string, string][]) : [])])}
      <div style="height:14px;line-height:14px;font-size:0;">&nbsp;</div>
      ${emailButton2(a.ctaUrl, a.mode === "card" ? "Update Payment Method" : "Top up wallet")}
    </div>`;
  const rows: string[] = [
    emailHero2({ eyebrow: "Renewal reminder", title: "Keep your\nserver online", text: lead, accent: "violet", badge: "clock" }),
    emailSection2(emailCard2(card, "22px 24px 24px"), "6px 40px 16px"),
    emailSection2(
      emailCardText2({
        title: "No downtime",
        text: a.mode === "card" ? "Keep your server online and your world running." : "Renewals that go through on time keep your server online.",
        icon: emailAsset("badges/shield-ok.png"),
      }),
      "0 40px 16px"
    ),
  ];
  if (art.known) rows.push(emailSection2(emailBannerArt2({ src: art.hero, h: 190, title: "Countless worlds.\nZero limits." }), "0 40px 22px"));
  return { template: "", subject: "", html: wrapEmail2(rows.join("\n"), { preheader: `${a.hostname} renews on ${a.date}.`, socials: a.socials }) };
}

