        : "That was the last automatic attempt.";
    return build({
      template: "paypal_payment_retry_failed",
      subject: `PayPal retry ${attempt} declined for ${hostname} — still running until ${finalDateFormatted}`,
      preheader: `${hostname} stays online until ${finalDateFormatted}. ${remainingLine}`,
      eyebrow: `Retry ${attempt} declined`,
      accent: "warn",
      heading: "Your PayPal account was declined again",
      blocks: [
        emailParagraph(
          `We tried your PayPal account for <b>${hostname}</b> again and it was declined. Checking your PayPal balance and any linked funding source is worth doing at this stage.`,
        ),
        stillRunning(hostname, `It stays online until <b>${finalDateFormatted}</b>.`),
        emailPanel(
