/**
 * Maintain the tracking inventory fixture (test/fixtures/email-tracking-inventory.json):
 *   { <sampleKey>: { subject, hrefs: [every absolute href, in order], unsubscribe: boolean } }
 *
 *   npx tsx scripts/email-inventory.ts            # print the CURRENT surface of every sample as JSON
 *   npx tsx scripts/email-inventory.ts --merge    # write the fixture: existing entries keep their
 *                                                 # baseline hrefs (captured from main before the
 *                                                 # overhaul), new sample keys are added from today's render
 *
 * `unsubscribe` is true when the template carries the (untracked, token-bearing)
 * one-click unsubscribe link, which is exactly when a marketing send must also
 * carry the List-Unsubscribe headers.
 */
import "../test/_cyrus-server-only-shim"; // no-op `server-only` + a closed DB port: rendering needs neither
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { SAMPLES, SAMPLE_UNSUB } from "../lib/email-samples";

const APP = process.env.APP_URL ?? "https://nxeon.cloud";
const file = join(__dirname, "..", "test", "fixtures", "email-tracking-inventory.json");
const current: Record<string, { subject: string; hrefs: string[]; unsubscribe: boolean }> = {};
for (const [key, build] of Object.entries(SAMPLES)) {
  try {
    const b = build();
    const hrefs = [...b.html.matchAll(/href="(https?:\/\/[^"]+)"/g)].map((m) => m[1].split(APP).join("{APP}"));
    current[key] = { subject: b.subject, hrefs, unsubscribe: b.html.includes(`href="${SAMPLE_UNSUB}"`) };
  } catch (e) {
    current[key] = { subject: `ERROR ${(e as Error).message}`, hrefs: [], unsubscribe: false };
  }
}
if (process.argv.includes("--merge")) {
  const old = JSON.parse(readFileSync(file, "utf8")) as Record<string, { subject: string; hrefs: string[]; unsubscribe?: boolean }>;
  const merged: typeof current = {};
  for (const k of Object.keys(current).sort()) merged[k] = old[k] ? { subject: old[k].subject, hrefs: old[k].hrefs, unsubscribe: current[k].unsubscribe } : current[k];
  writeFileSync(file, JSON.stringify(merged, null, 1) + "\n");
  console.log(`fixture: ${Object.keys(merged).length} templates (${Object.keys(merged).filter((k) => !old[k]).length} new)`);
} else {
  console.log(JSON.stringify(current, null, 1));
}
EOF
