import "./_cyrus-server-only-shim";
import { test } from "node:test";
import assert from "node:assert/strict";
import { existsSync, readFileSync, readdirSync, statSync } from "node:fs";
import { join, resolve } from "node:path";
import { SAMPLES, SAMPLE_UNSUB, SAMPLE_SOCIALS } from "../lib/email-samples";
import { sendMail, mailTestHooks, emails, type CapturedMail } from "../lib/mailer";
import { containsSecretQueryParam, wrapEmail, wrapEmail2 } from "../lib/email-render";
import { socialLinksFromValues, SOCIAL_PLATFORMS } from "../lib/social-links";
import { locationStatsFromRegions, uptimeLabel, locationsLine } from "../lib/email-stats";
import { renderNotification, SAMPLE_DATA } from "../lib/cyrus/notify/templates";

/**
 * Email rollout guard (2026-10): EVERY template goes through the real sendMail
 * path with the capture hook (nothing is delivered, nothing touches a DB) and
 * must come out with the tracking hooks intact, only configured social icons,
 * and only images that exist on disk.
 */
const APP = process.env.APP_URL ?? "https://nxeon.cloud";
const PUBLIC = resolve(__dirname, "..", "public");
const inventory = JSON.parse(readFileSync(join(__dirname, "fixtures", "email-tracking-inventory.json"), "utf8")) as Record<string, { subject: string; hrefs: string[]; unsubscribe: boolean }>;

async function viaSendMail(html: string, o: { unsub?: string; socials?: { key: string; href: string }[]; subject?: string } = {}): Promise<CapturedMail> {
  let got: CapturedMail | null = null;
  mailTestHooks.capture = (m) => void (got = m);
  mailTestHooks.socials = async () => o.socials ?? [];
  try {
    const ok = await sendMail({ to: "alex@example.com", subject: o.subject ?? "s", html, listUnsubscribeUrl: o.unsub });
    assert.equal(ok, true);
  } finally {
    mailTestHooks.capture = undefined;
    mailTestHooks.socials = undefined;
  }
  assert.ok(got, "captured");
  return got as CapturedMail;
}

const localFile = (u: string) => {
  assert.ok(u.startsWith(APP + "/"), `image must be an absolute app URL: ${u}`);
  return join(PUBLIC, decodeURIComponent(new URL(u).pathname));
};

test("every sample has a fixture entry (a new template cannot skip the tracking inventory)", () => {
  assert.deepEqual(Object.keys(SAMPLES).filter((k) => !(k in inventory)), []);
});

for (const [key, build] of Object.entries(SAMPLES)) {
  test(`${key}: sendMail capture, tracked links, headers, socials, images`, async () => {
    const b = build();
    const marketing = inventory[key].unsubscribe;
    assert.equal(b.html.includes(`href="${SAMPLE_UNSUB}"`), marketing, "fixture unsubscribe flag matches the template");

    const m = await viaSendMail(b.html, { unsub: marketing ? SAMPLE_UNSUB : undefined, subject: b.subject });
    // open pixel: exactly one, before </body>
    assert.equal((m.html.match(/\/api\/track\/email\/[^/]+\/open/g) ?? []).length, 1, "one open pixel");
    assert.ok(m.html.trimEnd().endsWith("</body></html>") || m.html.trimEnd().endsWith("</html>"));
    // click rewrite with the real destinations recorded; secret + unsubscribe links stay direct
    for (const h of [...b.html.matchAll(/href="(https?:\/\/[^"]+)"/g)].map((x) => x[1])) {
      const direct = containsSecretQueryParam(h) || h.includes("/api/outreach/unsubscribe") || h === SAMPLE_UNSUB;
      if (direct) assert.ok(m.html.includes(`href="${h}"`), `must stay direct: ${h}`);
      else assert.ok(m.links.includes(h), `not tracked: ${h}`);
    }
    // marketing: one-click List-Unsubscribe; transactional: none
    if (marketing) {
      assert.equal(m.headers["List-Unsubscribe"], `<${SAMPLE_UNSUB}>`);
      assert.equal(m.headers["List-Unsubscribe-Post"], "List-Unsubscribe=One-Click");
    } else assert.deepEqual(m.headers, {});
    // plain text part has content and no markup
    assert.ok(m.text.length > 40 && !/<\w+|@media/.test(m.text));
    // images: absolute app URL, png/jpg, size + alt attributes, file exists
    const srcs = [...b.html.matchAll(/<img\b[^>]*>/g)].map((x) => x[0]);
    for (const tag of srcs) {
      const src = /src="([^"]+)"/.exec(tag)?.[1] ?? "";
      assert.match(src, /\.(png|jpe?g)$/i, `png/jpg only: ${src}`);
      assert.match(tag, /\bwidth="\d+"/);
      assert.match(tag, /\bheight="\d+"/);
      assert.match(tag, /\balt="/);
      assert.ok(existsSync(localFile(src)), `missing file for ${src}`);
    }
    for (const bg of [...b.html.matchAll(/(?:background="|url\('?)(https?:\/\/[^"')]+)/g)].map((x) => x[1])) {
      assert.match(bg, /\.(png|jpe?g)$/i, `bg png/jpg: ${bg}`);
      assert.ok(existsSync(localFile(bg)), `missing bg file ${bg}`);
    }
    assert.ok(!/<link\b[^>]*href=/.test(b.html), "no <link href> (rewritten by click tracking)");
  });
}

test("footer social icons equal the configured Admin Settings values and nothing renders when unset", async () => {
  // nothing configured -> no icon row at all
  assert.deepEqual(socialLinksFromValues({}), []);
  assert.deepEqual(socialLinksFromValues({ social_discord: "   ", social_twitter: "not a url", social_youtube: "javascript:alert(1)" }), []);
  const bare = await viaSendMail(emails.welcome("Alex").html, { socials: [] });
  assert.ok(!bare.html.includes("/email/social/"), "no icon when nothing is configured");
  assert.ok(!bare.html.includes("<!--nx-socials-->"), "marker resolved");

  // configured -> exactly those, in platform order, with the saved URL
  const values = { social_discord: "https://discord.gg/hqVZdDJH2", social_youtube: "https://youtube.com/@nxeon", social_twitter: "", social_instagram: " https://instagram.com/nxeon " };
  const cfg = socialLinksFromValues(values).map((s) => ({ key: s.key as string, href: s.href }));
  assert.deepEqual(cfg.map((s) => s.key).sort(), ["discord", "instagram", "youtube"]);
